      state.backed = true;
      own(container, 'attrs', 'data-ds-glide');
      own(container, 'props', '--ds-flip-backdrop');
      const backdrop = known ?? backdropOf(container);
      if (backdrop) container.style.setProperty('--ds-flip-backdrop', backdrop);
